import 'dart:convert';

import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../core/games/game_record.dart';
import '../../core/games/library.dart';
import '../../core/games/pgn.dart';

/// The bundled library (SLAVNE_PARTIE_PLAN §3), generated by
/// tool/games/build.dart.
const libraryRoot = 'assets/games';

final libraryIndexProvider = FutureProvider<List<ShelfRef>>((ref) async {
  final text = await rootBundle.loadString('$libraryRoot/index.json');
  return parseLibraryIndex(jsonDecode(text) as Map<String, dynamic>);
});

/// Groups of one shelf: golden, matches, women.
final shelfProvider = FutureProvider.family<List<LibraryGroup>, String>((ref, shelfId) async {
  final index = await ref.watch(libraryIndexProvider.future);
  final shelf = index.firstWhere((s) => s.id == shelfId);
  final text = await rootBundle.loadString('$libraryRoot/${shelf.file}');
  return parseCollection(jsonDecode(text) as Map<String, dynamic>);
});

/// One group by id across all shelves (a match, a champion).
final groupProvider = FutureProvider.family<LibraryGroup?, String>((ref, groupId) async {
  for (final s in await ref.watch(libraryIndexProvider.future)) {
    for (final g in await ref.watch(shelfProvider(s.id).future)) {
      if (g.id == groupId) return g;
    }
  }
  return null;
});

/// Parsed PGN pack; kept while the app runs (packs are small).
final _packProvider = FutureProvider.family<List<PgnGame>, String>((ref, pack) async {
  ref.keepAlive();
  return parsePgn(await rootBundle.loadString('$libraryRoot/p/$pack.pgn'));
});

/// A game by its stable id.
final gameByIdProvider = FutureProvider.family<GameRecord?, String>((ref, id) async {
  for (final s in await ref.watch(libraryIndexProvider.future)) {
    for (final g in await ref.watch(shelfProvider(s.id).future)) {
      for (final e in g.entries) {
        if (e.id != id) continue;
        final games = await ref.watch(_packProvider(e.pack).future);
        return GameRecord.fromPgn(games[e.index]);
      }
    }
  }
  return null;
});
